import{_ as p,a0 as h,w as o,s as r,ao as l,I as e,x as i,a1 as n,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何使用 SSHFS 通过 SSH 挂载远程的 Linux 文件系统或者目录 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 SSHFS 通过 SSH 挂载远程的 Linux 文件系统或者目录 | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 SSHFS 通过 SSH 挂载远程的 Linux 文件系统或者目录 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 SSHFS 通过 SSH 挂载远程的 Linux 文件系统或者目录 | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20160811 How to Mount Remote Linux Filesystem or Directory Using SSHFS Over SSH","title":"如何使用 SSHFS 通过 SSH 挂载远程的 Linux 文件系统或者目录","tag":"201610","desc":""},"relativePath":"201610/20160811 How to Mount Remote Linux Filesystem or Directory Using SSHFS Over SSH.md","filePath":"[post].md"}'),d={name:"201610/20160811 How to Mount Remote Linux Filesystem or Directory Using SSHFS Over SSH.md"};function u(m,s,g,c,S,f){const t=h("Link");return o(),r("div",null,[s[19]||(s[19]=l('<h1 id="如何使用-sshfs-通过-ssh-挂载远程的-linux-文件系统或者目录" tabindex="-1">如何使用 SSHFS 通过 SSH 挂载远程的 Linux 文件系统或者目录 <a class="header-anchor" href="#如何使用-sshfs-通过-ssh-挂载远程的-linux-文件系统或者目录" aria-label="Permalink to “如何使用 SSHFS 通过 SSH 挂载远程的 Linux 文件系统或者目录”">​</a></h1><p>写这篇文章的主要目的就是提供一步一步的指导，关于如何使用 SSHFS 通过 SSH 挂载远程的 Linux 文件系统或目录。</p><p>这篇文章对于那些无论出于什么目的，希望在他们本地的系统中挂载远程的文件系统的用户或者系统管理员有帮助。我们通过 Linux 系统中的一个安装了 SSHFS 客户端进行实际测试，并且成功的挂载了远程的文件系统。</p><p>在我们进一步安装之前，让我们了解一下 SSHFS 的相关内容，以及它是如何工作的。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2012/08/Sshfs-Mount-Remote-Linux-Filesystem-Directory.png" alt=""><em>Sshfs 挂载远程的 Linux 文件系统或者目录</em></p><h3 id="什么是-sshfs" tabindex="-1">什么是 SSHFS？ <a class="header-anchor" href="#什么是-sshfs" aria-label="Permalink to “什么是 SSHFS？”">​</a></h3><p>SSHFS（Secure SHell FileSystem）是一个客户端，可以让我们通过 SSH 文件传输协议（SFTP）挂载远程的文件系统并且在本地机器上和远程的目录和文件进行交互。</p><p>SFTP 是一种通过 SSH 协议提供文件访问、文件传输和文件管理功能的安全文件传输协议。因为 SSH 在网络中从一台电脑到另一台电脑传输文件的时候使用数据加密通道，并且 SSHFS 内置在 FUSE（用户空间的文件系统）内核模块，允许任何非特权用户在不修改内核代码的情况下创建他们自己的文件系统。</p><p>在这篇文章中，我们将会向你展示在任意 Linux 发行版上如何安装并且使用 SSHFS 客户端，在本地 Linux 机器上挂载远程的 Linux 文件系统或者目录。</p><h4 id="步骤1-在-linux-系统上安装-sshfs" tabindex="-1">步骤1：在 Linux 系统上安装 SSHFS <a class="header-anchor" href="#步骤1-在-linux-系统上安装-sshfs" aria-label="Permalink to “步骤1：在 Linux 系统上安装 SSHFS”">​</a></h4>',10)),e("p",null,[s[1]||(s[1]=i("默认情况下，sshfs 包不存在所有的主流 Linux 发行版中，你需要在你的 Linux 系统中启用 ",-1)),n(t,{href:"https://linux.cn/article-2324-1.html"},{default:a(()=>[...s[0]||(s[0]=[i("epel 仓库",-1)])]),_:1}),s[2]||(s[2]=i("，在 Yum 命令行的帮助下安装 SSHFS 及其依赖。",-1))]),s[20]||(s[20]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install sshfs</span></span>
<span class="line"><span># dnf install sshfs              【在 Fedora 22+ 发行版上】</span></span>
<span class="line"><span>$ sudo apt-get install sshfs     【基于 Debian/Ubuntu 的系统】</span></span></code></pre></div><h4 id="步骤2-创建-sshfs-挂载目录" tabindex="-1">步骤2：创建 SSHFS 挂载目录 <a class="header-anchor" href="#步骤2-创建-sshfs-挂载目录" aria-label="Permalink to “步骤2：创建 SSHFS 挂载目录”">​</a></h4><p>当你安装 SSHFS 包之后，你需要创建一个挂载点目录，在这儿你将要挂载你的远程文件系统。例如，我们在 /mnt/tecmint 下创建挂载目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mkdir /mnt/tecmint</span></span>
<span class="line"><span>$ sudo mkdir /mnt/tecmint     【基于 Debian/Ubuntu 的系统】</span></span></code></pre></div><h3 id="步骤-3-使用-sshfs-挂载远程的文件系统" tabindex="-1">步骤 3：使用 SSHFS 挂载远程的文件系统 <a class="header-anchor" href="#步骤-3-使用-sshfs-挂载远程的文件系统" aria-label="Permalink to “步骤 3：使用 SSHFS 挂载远程的文件系统”">​</a></h3><p>当你已经创建你的挂载点目录之后，现在使用 root 用户运行下面的命令行，在 /mnt/tecmint 目录下挂载远程的文件系统。视你的情况挂载目录可以是任何目录。</p><p>下面的命令行将会在本地的 /mnt/tecmint 目录下挂载一个叫远程的一个 /home/tecmint 目录。（不要忘了使用你的 IP 地址和挂载点替换 x.x.x.x）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sshfs tecmint@x.x.x.x:/home/tecmint/ /mnt/tecmint</span></span>
<span class="line"><span>$ sudo sshfs -o allow_other tecmint@x.x.x.x:/home/tecmint/ /mnt/tecmint      【基于 Debian/Ubuntu 的系统】</span></span></code></pre></div><p>如果你的 Linux 服务器配置为基于 SSH 密钥授权，那么你将需要使用如下所示的命令行指定你的公共密钥的路径。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sshfs -o IdentityFile=~/.ssh/id_rsa tecmint@x.x.x.x:/home/tecmint/ /mnt/tecmint</span></span>
<span class="line"><span>$ sudo sshfs -o allow_other,IdentityFile=~/.ssh/id_rsa tecmint@x.x.x.x:/home/tecmint/ /mnt/tecmint     【基于 Debian/Ubuntu 的系统】</span></span></code></pre></div><h4 id="步骤-4-验证远程的文件系统挂载成功" tabindex="-1">步骤 4：验证远程的文件系统挂载成功 <a class="header-anchor" href="#步骤-4-验证远程的文件系统挂载成功" aria-label="Permalink to “步骤 4：验证远程的文件系统挂载成功”">​</a></h4><p>如果你已经成功的运行了上面的命令并且没有任何错误，你将会看到挂载在 /mnt/tecmint 目录下的远程的文件和目录的列表</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cd /mnt/tecmint</span></span>
<span class="line"><span># ls</span></span>
<span class="line"><span>[root@ tecmint]# ls</span></span>
<span class="line"><span>12345.jpg                       ffmpeg-php-0.6.0.tbz2                Linux                                           news-closeup.xsl     s3.jpg</span></span>
<span class="line"><span>cmslogs                         gmd-latest.sql.tar.bz2               Malware                                         newsletter1.html     sshdallow</span></span>
<span class="line"><span>epel-release-6-5.noarch.rpm     json-1.2.1                           movies_list.php                                 pollbeta.sql</span></span>
<span class="line"><span>ffmpeg-php-0.6.0                json-1.2.1.tgz                       my_next_artical_v2.php                          pollbeta.tar.bz2</span></span></code></pre></div><h4 id="步骤-5-使用-df-ht-命令检查挂载点" tabindex="-1">步骤 5：使用 df -hT 命令检查挂载点 <a class="header-anchor" href="#步骤-5-使用-df-ht-命令检查挂载点" aria-label="Permalink to “步骤 5：使用 df -hT 命令检查挂载点”">​</a></h4><p>如果你运行 df -hT命令，你将会看到远程文件系统的挂载点。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># df -hT</span></span></code></pre></div><p>样本输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Filesystem                          Type        Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>udev                                devtmpfs    730M     0  730M   0% /dev</span></span>
<span class="line"><span>tmpfs                               tmpfs       150M  4.9M  145M   4% /run</span></span>
<span class="line"><span>/dev/sda1                           ext4         31G  5.5G   24G  19% /</span></span>
<span class="line"><span>tmpfs                               tmpfs       749M  216K  748M   1% /dev/shm</span></span>
<span class="line"><span>tmpfs                               tmpfs       5.0M  4.0K  5.0M   1% /run/lock</span></span>
<span class="line"><span>tmpfs                               tmpfs       749M     0  749M   0% /sys/fs/cgroup</span></span>
<span class="line"><span>tmpfs                               tmpfs       150M   44K  150M   1% /run/user/1000</span></span>
<span class="line"><span>tecmint@192.168.0.102:/home/tecmint fuse.sshfs  324G   55G  253G  18% /mnt/tecmint</span></span></code></pre></div><h4 id="步骤-6-永久挂载远程文件系统" tabindex="-1">步骤 6：永久挂载远程文件系统 <a class="header-anchor" href="#步骤-6-永久挂载远程文件系统" aria-label="Permalink to “步骤 6：永久挂载远程文件系统”">​</a></h4><p>为了永久的挂载远程的文件系统，你需要修改一个叫 <code>/etc/fstab</code> 的文件。照着做，使用你最喜欢的编辑器打开文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/fstab</span></span>
<span class="line"><span>$ sudo vi /etc/fstab     【基于 Debian/Ubuntu 的系统】</span></span></code></pre></div><p>移动到文件的底部并且添加下面的一行，保存文件并退出。下面条目表示使用默认的设置挂载远程的文件系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sshfs#tecmint@x.x.x.x:/home/tecmint/ /mnt/tecmint fuse.sshfs defaults 0 0</span></span></code></pre></div>`,23)),e("p",null,[s[4]||(s[4]=i("确保服务器之间允许 ",-1)),n(t,{href:"https://linux.cn/article-5444-1.html"},{default:a(()=>[...s[3]||(s[3]=[i("SSH 无密码登录",-1)])]),_:1}),s[5]||(s[5]=i("，这样系统重启之后才能自动挂载文件系统。",-1))]),s[21]||(s[21]=l(`<p>如果你的服务器配置为基于 SSH 密钥的认证方式，请加入如下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sshfs#tecmint@x.x.x.x:/home/tecmint/ /mnt/tecmint fuse.sshfs IdentityFile=~/.ssh/id_rsa defaults 0 0</span></span></code></pre></div><p>接下来，你需要更新 fstab 文件使修改生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount -a</span></span>
<span class="line"><span>$ sudo mount -a   【基于 Debian/Ubuntu 的系统】</span></span></code></pre></div><h4 id="步骤-7-卸载远程的文件系统" tabindex="-1">步骤 7：卸载远程的文件系统 <a class="header-anchor" href="#步骤-7-卸载远程的文件系统" aria-label="Permalink to “步骤 7：卸载远程的文件系统”">​</a></h4><p>为了卸载远程的文件系统，只需要发出以下的命令即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># umount /mnt/tecmint</span></span></code></pre></div><p>目前为止就这样了，如果你在挂载远程文件系统的时候遇到任何问题或者需要任何帮助，请通过评论联系我们，如果你感觉这篇文章非常有用，请分享给你的朋友们。</p><hr>`,9)),e("p",null,[s[7]||(s[7]=i("via: ",-1)),n(t,{href:"http://www.tecmint.com/sshfs-mount-remote-linux-filesystem-directory-using-ssh/"},{default:a(()=>[...s[6]||(s[6]=[i("http://www.tecmint.com/sshfs-mount-remote-linux-filesystem-directory-using-ssh/",-1)])]),_:1})]),e("p",null,[s[11]||(s[11]=i("作者：",-1)),n(t,{href:"http://www.tecmint.com/author/admin/"},{default:a(()=>[...s[8]||(s[8]=[i("Ravi Saive",-1)])]),_:1}),s[12]||(s[12]=i(" 译者：",-1)),n(t,{href:"https://github.com/yangmingming"},{default:a(()=>[...s[9]||(s[9]=[i("yangmingming",-1)])]),_:1}),s[13]||(s[13]=i(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[10]||(s[10]=[i("wxy",-1)])]),_:1})]),e("p",null,[s[16]||(s[16]=i("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[14]||(s[14]=[i("LCTT",-1)])]),_:1}),s[17]||(s[17]=i(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:a(()=>[...s[15]||(s[15]=[i("Linux中国",-1)])]),_:1}),s[18]||(s[18]=i(" 荣誉推出",-1))])])}const y=p(d,[["render",u]]);export{x as __pageData,y as default};
